const config = $input.item.json;
const body = $('Gather Result').item.json.body || {};
return [{ json: {
  ...config,
  digits: body.Digits,
  callerNumber: body.From,
  calledNumber: body.To,
} }];

const body = $json.body || {};
return [{ json: {
  dialCallStatus: body.DialCallStatus || 'unknown',
  dialCallDuration: body.DialCallDuration || null,
  callSid: body.CallSid || null,
  callerNumber: body.From || null,
  calledNumber: body.To || null,
} }];

const config = $input.item.json;
const status = $('Parse Dial Status').item.json;
return [{ json: { ...status, ...config } }];

const d = $input.item.json;
return [{ json: {
  ...d,
  twiml: `<?xml version="1.0" encoding="UTF-8"?>\n<Response>\n  <Say voice="Polly.Amy-Neural" language="en-GB">Sorry, I'm having trouble connecting you to booking right now. Let me put you through to the team instead.</Say>\n  <Dial>${d.receptionForwardNumber}</Dial>\n</Response>`,
} }];

