let call = {};
for (const nm of ['Inbound Call', 'Gather Result', 'Dial Status Callback']) { try { call = $(nm).first().json.body || {}; if (call.From) break; } catch (e) {} }
const twiml = '<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="Polly.Amy-Neural" language="en-GB">Sorry, we can\'t take your call right now. Please leave your name, number and a short message after the tone and we\'ll call you back.</Say><Record maxLength="120" playBeep="true"/></Response>';
return [{ json: { twiml, notice: { kind: 'urgent_call', audience: 'bilal', text: 'Phone line problem: a call from ' + (call.From || 'unknown') + ' to ' + (call.To || 'unknown') + ' could not be matched to a client (Client Config failed). The caller was sent to voicemail. Check My Clients > Business phone number.' } } }];

